  organ: { brr: 'wgRmVUMiIiH/p0XZ0P7+u+3V', loop: 0, base: 1000 },
  strings: { brr: 'wgZWVVVEMyIRn4IODg4OHEt4', loop: 0, base: 1000 },
  brass: { brr: 'wgVkMiEREREApwD/D///3umT', loop: 0, base: 1000 },
  choir: { brr: 'wgJFZmZUMiIhmw8jDr7xEPI3', loop: 0, base: 1000 },
