    if (p + 8 > b.length) throw new RangeError('MIDI file is cut short');
    if (str() !== 'MTrk') { p += 4; const l = u32(); p += l; t--; if (p >= b.length) break; continue; }
    p += 4; const len = u32(), end = p + len;
