      if (s === 0xFF) {
        const type = b[p++]; let l = 0; do { c = b[p++]; l = (l << 7) | (c & 127); } while (c & 128);
        if (type === 0x51 && l === 3) raw.push({ tick, tr: t, n: order++, type: 'tempo', us: b[p] << 16 | b[p + 1] << 8 | b[p + 2] });
        p += l; continue;
      }
